/**
 * Grafana k6 load test for File Upload API (openapi.yaml).
 *
 * Per-iteration flow:
 *   1. POST   /api/v1/files                  (upload)
 *   2. GET    /api/v1/files                  (query/list)
 *   3. GET    /api/v1/files/{id}/content     (get file)
 *   4. DELETE /api/v1/files/{id}             (delete)
 *
 * Required env (set by run_load_test.sh):
 *   BASE_URL   - e.g. http://127.0.0.1:5000
 *   DATA_FILE  - path to binary payload generated by the shell script
 *   FILE_NAME  - original filename sent in multipart upload
 *   ENCRYPT    - "true" | "false" (default false)
 */
import http from 'k6/http';
import { check, group } from 'k6';
import { Rate, Trend } from 'k6/metrics';

const BASE_URL = (__ENV.BASE_URL || 'http://127.0.0.1:5000').replace(/\/$/, '');
const DATA_FILE = __ENV.DATA_FILE || '';
const FILE_NAME = __ENV.FILE_NAME || 'loadtest.bin';
const ENCRYPT = (__ENV.ENCRYPT || 'false').toLowerCase() === 'true' ? 'true' : 'false';

if (!DATA_FILE) {
  throw new Error('DATA_FILE env var is required (path to generated payload)');
}

// open() must run in init context
const fileBytes = open(DATA_FILE, 'b');

const uploadTrend = new Trend('file_upload_duration', true);
const listTrend = new Trend('file_list_duration', true);
const downloadTrend = new Trend('file_download_duration', true);
const deleteTrend = new Trend('file_delete_duration', true);
const flowErrorRate = new Rate('file_flow_errors');

export const options = {
  thresholds: {
    http_req_failed: ['rate<0.05'],
    file_flow_errors: ['rate<0.05'],
    checks: ['rate>0.95'],
  },
  // VUs / iterations are supplied via CLI: k6 run --vus N --iterations M
  summaryTrendStats: ['avg', 'min', 'med', 'p(90)', 'p(95)', 'p(99)', 'max'],
};

function requestId() {
  return `k6-${__VU}-${__ITER}-${Date.now()}`;
}

function commonHeaders() {
  return { 'X-Request-Id': requestId() };
}

export default function () {
  let fileId = null;
  let failed = false;

  group('1_upload', function () {
    const res = http.post(
      `${BASE_URL}/api/v1/files`,
      {
        file: http.file(fileBytes, FILE_NAME, 'application/octet-stream'),
        encrypt: ENCRYPT,
      },
      {
        headers: commonHeaders(),
        tags: { endpoint: 'upload' },
      }
    );
    uploadTrend.add(res.timings.duration);

    const ok = check(res, {
      'upload status 201': (r) => r.status === 201,
      'upload has id': (r) => {
        try {
          const body = r.json();
          return body && typeof body.id === 'string' && body.id.length > 0;
        } catch (e) {
          return false;
        }
      },
    });

    if (!ok) {
      failed = true;
      return;
    }
    fileId = res.json('id');
  });

  if (fileId) {
    group('2_query', function () {
      const res = http.get(`${BASE_URL}/api/v1/files?limit=20&offset=0`, {
        headers: commonHeaders(),
        tags: { endpoint: 'list' },
      });
      listTrend.add(res.timings.duration);

      const ok = check(res, {
        'list status 200': (r) => r.status === 200,
        'list has files array': (r) => {
          try {
            const body = r.json();
            return body && Array.isArray(body.files) && typeof body.total === 'number';
          } catch (e) {
            return false;
          }
        },
      });
      if (!ok) {
        failed = true;
      }
    });

    group('3_get_file', function () {
      const res = http.get(`${BASE_URL}/api/v1/files/${fileId}/content`, {
        headers: commonHeaders(),
        tags: { endpoint: 'download' },
        responseType: 'binary',
      });
      downloadTrend.add(res.timings.duration);

      const ok = check(res, {
        'download status 200': (r) => r.status === 200,
        'download has body': (r) => r.body && r.body.byteLength > 0,
        'download content-disposition': (r) => {
          const cd = String(
            r.headers['Content-Disposition'] || r.headers['content-disposition'] || ''
          );
          return cd.toLowerCase().includes('attachment');
        },
      });
      if (!ok) {
        failed = true;
      }
    });

    group('4_delete', function () {
      const res = http.del(`${BASE_URL}/api/v1/files/${fileId}`, null, {
        headers: commonHeaders(),
        tags: { endpoint: 'delete' },
      });
      deleteTrend.add(res.timings.duration);

      const ok = check(res, {
        'delete status 204': (r) => r.status === 204,
      });
      if (!ok) {
        failed = true;
      }
    });
  }

  flowErrorRate.add(failed ? 1 : 0);
}
